// DCNetLabServer is the server API for DCNetLab service.
// All implementations must embed UnimplementedDCNetLabServer
// for forward compatibility.
//
// DCNetLab is the controller service: lab lifecycle, plan/apply,
// topology queries and async operation tracking.
type DCNetLabServer interface {
	// --- Labs ---
	CreateLab(context.Context, *CreateLabRequest) (*Lab, error)
	ListLabs(context.Context, *ListLabsRequest) (*ListLabsReply, error)
	GetLab(context.Context, *GetLabRequest) (*Lab, error)
	DeleteLab(context.Context, *DeleteLabRequest) (*OperationRef, error)
	// StartLab / StopLab power the deployed containers of a lab on and
	// off (docker start/stop) without touching the generation.
	StartLab(context.Context, *StartLabRequest) (*OperationRef, error)
	StopLab(context.Context, *StopLabRequest) (*OperationRef, error)
	// RepairLab re-attaches any simulated interfaces the runtime lost
	// (e.g. a host Docker daemon restart dropping veth pairs) without
	// going through Plan/Apply: it re-runs the same idempotent deploy
	// against the lab's current generation, so already-running
	// containers and their programs are left untouched.
	RepairLab(context.Context, *RepairLabRequest) (*OperationRef, error)
	// --- Topology ---
	ListNodes(context.Context, *ListNodesRequest) (*ListNodesReply, error)
	ListLinks(context.Context, *ListLinksRequest) (*ListLinksReply, error)
	ListAllocations(context.Context, *ListAllocationsRequest) (*ListAllocationsReply, error)
	// StartNode / StopNode power a single device on and off.
	StartNode(context.Context, *StartNodeRequest) (*Node, error)
	StopNode(context.Context, *StopNodeRequest) (*Node, error)
	// GetNodeRuntime returns the management view of one deployed node:
	// the underlying container state and every kernel interface inside
	// it, including implementation plumbing (bridge, VRRP macvlan,
	// management eth0) that the simulated topology does not model.
	GetNodeRuntime(context.Context, *GetNodeRuntimeRequest) (*NodeRuntime, error)
	// GetNodeBGP returns the BGP configuration of one node as derived
	// by the FRR compiler from the topology model: eBGP neighbors over
	// fabric links, the MLAG iBGP session and the leaf's dynamic server
	// peer-group. Empty for nodes that do not run BGP.
	GetNodeBGP(context.Context, *GetNodeBGPRequest) (*NodeBGP, error)
	// GetNodeRoutes returns the live IPv4 routing table (FRR RIB) of
	// one deployed node; routes are empty unless the container is
	// running.
	GetNodeRoutes(context.Context, *GetNodeRoutesRequest) (*NodeRoutes, error)
	// GetNodeBGPTable returns the live BGP Loc-RIB of one deployed
	// node (`show ip bgp`): every candidate path per prefix, before
	// best-path selection reduces them to the RIB entry.
	GetNodeBGPTable(context.Context, *GetNodeBGPTableRequest) (*NodeBGPTable, error)
	// GetNodeFIB returns the live kernel forwarding table of one
	// deployed node (`ip route`): what actually forwards packets, as
	// installed by zebra from the RIB.
	GetNodeFIB(context.Context, *GetNodeFIBRequest) (*NodeFIB, error)
	// GetNodeMTR runs a one-shot mtr diagnostic probe from a deployed
	// node toward a target (another lab node or an arbitrary
	// address/hostname), reporting per-hop loss/latency statistics.
	// Hops whose address is known to the lab's model resolve back to a
	// node, letting the UI highlight the measured path on the topology
	// graph.
	GetNodeMTR(context.Context, *GetNodeMTRRequest) (*NodeMTR, error)
	// ScanMTRPaths repeats an mtr probe several times to sample
	// different ECMP branches: each run is a fresh process, so tcp/udp
	// naturally gets a new ephemeral source port per run — the same
	// 5-tuple hashing a real flow would use — varying which ECMP branch
	// the fabric picks. Distinct paths are grouped with how many
	// samples measured each one. icmp is rejected: it carries no port,
	// so every run would hash to the same branch.
	ScanMTRPaths(context.Context, *ScanMTRPathsRequest) (*MTRPathScan, error)
	// GetNodeMetrics samples resource usage of one server live from
	// its agent, node-exporter style: CPU, memory, load, filesystem,
	// disk I/O and per-interface network.
	GetNodeMetrics(context.Context, *GetNodeMetricsRequest) (*NodeMetrics, error)
	// GetNodeMetricsHistory returns the collected resource-usage time
	// series of one server: 15 s points from the controller's metrics
	// collector, kept 2 h in memory and 24 h on disk.
	GetNodeMetricsHistory(context.Context, *GetNodeMetricsHistoryRequest) (*NodeMetricsHistory, error)
	// --- Packages ---
	// Packages are versioned program artifacts (tar.gz with a
	// manifest.json) in the controller's repository; lab servers
	// install them through their agent. The bundled lab-app registers
	// as the builtin package; uploads use the same pipeline.
	UploadPackage(context.Context, *UploadPackageRequest) (*Package, error)
	ListPackages(context.Context, *ListPackagesRequest) (*ListPackagesReply, error)
	DeletePackage(context.Context, *DeletePackageRequest) (*DeletePackageReply, error)
	// GetNodeInventory reports what is actually on one server, live
	// from its agent: installed package versions and every program
	// (controller-managed or created node-locally via the in-container
	// CLI).
	GetNodeInventory(context.Context, *GetNodeInventoryRequest) (*NodeInventory, error)
	// InstallPackage delivers a package version onto lab servers
	// without declaring a program — the "deploy a binary" path (apt
	// install without a service unit). Idempotent per server: agents
	// skip versions already present with the same digest.
	InstallPackage(context.Context, *InstallPackageRequest) (*InstallPackageReply, error)
	// --- Programs ---
	// Programs are supervised processes on lab servers, each running
	// the entrypoint of an installed Package version, managed through
	// the per-server dcnetlab-server-agent.
	CreateProgram(context.Context, *CreateProgramRequest) (*CreateProgramReply, error)
	ListPrograms(context.Context, *ListProgramsRequest) (*ListProgramsReply, error)
	StartProgram(context.Context, *ProgramOpRequest) (*Program, error)
	StopProgram(context.Context, *ProgramOpRequest) (*Program, error)
	UpgradeProgram(context.Context, *UpgradeProgramRequest) (*Program, error)
	DeleteProgram(context.Context, *ProgramOpRequest) (*DeleteProgramReply, error)
	// BatchProgramOp starts, stops or deletes several programs at once
	// (op is start|stop|delete); each id is applied best-effort and its
	// outcome is reported, so one failure does not abort the rest.
	BatchProgramOp(context.Context, *BatchProgramRequest) (*BatchProgramReply, error)
	GetProgramLogs(context.Context, *GetProgramLogsRequest) (*ProgramLogs, error)
	// --- Traffic ---
	// TrafficScenarios drive measurable traffic between two lab servers
	// through a pair of trafficgen Programs (server role on the
	// destination, client role on the source); the collector tails the
	// client's stat lines into rate/success-rate/latency metrics and
	// evaluates any configured assertions.
	CreateTrafficScenario(context.Context, *CreateTrafficScenarioRequest) (*TrafficScenario, error)
	ListTrafficScenarios(context.Context, *ListTrafficScenariosRequest) (*ListTrafficScenariosReply, error)
	StartTrafficScenario(context.Context, *TrafficScenarioOpRequest) (*TrafficScenario, error)
	StopTrafficScenario(context.Context, *TrafficScenarioOpRequest) (*TrafficScenario, error)
	DeleteTrafficScenario(context.Context, *TrafficScenarioOpRequest) (*DeleteTrafficScenarioReply, error)
	// GetTrafficScenarioHistory returns the collected metrics series of
	// one scenario: 5 s points kept in memory for up to one hour
	// (scenarios are short interactive experiments, not persisted
	// across a controller restart like server metrics).
	GetTrafficScenarioHistory(context.Context, *GetTrafficScenarioHistoryRequest) (*TrafficScenarioHistory, error)
	// --- Fault ---
	// FaultScenarios inject and recover a controlled failure against a
	// node or a link: node-stop/node-restart reuse the same pause/
	// unpause power semantics as the topology page; link-down and
	// interface-down set the interface administratively down; impairment
	// shapes egress traffic with one netem qdisc (delay/jitter/loss/rate
	// combined, matching how netem itself works — there is only ever one
	// qdisc per interface). A target (node or link) allows at most one
	// applied scenario at a time.
	CreateFaultScenario(context.Context, *CreateFaultScenarioRequest) (*FaultScenario, error)
	ListFaultScenarios(context.Context, *ListFaultScenariosRequest) (*ListFaultScenariosReply, error)
	ApplyFaultScenario(context.Context, *FaultScenarioOpRequest) (*FaultScenario, error)
	RecoverFaultScenario(context.Context, *FaultScenarioOpRequest) (*FaultScenario, error)
	DeleteFaultScenario(context.Context, *FaultScenarioOpRequest) (*DeleteFaultScenarioReply, error)
	// --- Capture ---
	// CaptureSessions record packets on one modelled interface of a lab
	// node (a topology link endpoint or vlanif/bond0) into a pcapng
	// file, with per-packet metadata available live. A session starts
	// capturing on creation and ends by itself (duration or limit) or
	// via stop; the recording stays downloadable until the session is
	// deleted or expires. The pcapng download is a plain HTTP route
	// (GET /api/v1/labs/{lab_id}/captures/{id}/pcap) and live metadata
	// is also pushed on WS /ws/v1/labs/{lab_id}/captures/{id}.
	CreateCaptureSession(context.Context, *CreateCaptureSessionRequest) (*CaptureSession, error)
	ListCaptureSessions(context.Context, *ListCaptureSessionsRequest) (*ListCaptureSessionsReply, error)
	GetCaptureSession(context.Context, *CaptureSessionOpRequest) (*CaptureSession, error)
	StopCaptureSession(context.Context, *CaptureSessionOpRequest) (*CaptureSession, error)
	DeleteCaptureSession(context.Context, *CaptureSessionOpRequest) (*DeleteCaptureSessionReply, error)
	ListCapturePackets(context.Context, *ListCapturePacketsRequest) (*ListCapturePacketsReply, error)
	GetCapturePacket(context.Context, *GetCapturePacketRequest) (*CapturePacketDetail, error)
	// --- Plans ---
	CreatePlan(context.Context, *CreatePlanRequest) (*Plan, error)
	GetPlan(context.Context, *GetPlanRequest) (*Plan, error)
	ApplyPlan(context.Context, *ApplyPlanRequest) (*OperationRef, error)
	// --- Operations & Generations ---
	GetOperation(context.Context, *GetOperationRequest) (*Operation, error)
	ListOperations(context.Context, *ListOperationsRequest) (*ListOperationsReply, error)
	ListGenerations(context.Context, *ListGenerationsRequest) (*ListGenerationsReply, error)
	// --- Profiles & health ---
	ListProfiles(context.Context, *ListProfilesRequest) (*ListProfilesReply, error)
	Healthz(context.Context, *HealthzRequest) (*HealthzReply, error)
	mustEmbedUnimplementedDCNetLabServer()
}

